import { sql } from "drizzle-orm";
import {
  bigserial,
  boolean,
  index,
  jsonb,
  pgTable,
  real,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

/**
 * Core tables shared by every module.
 * Modules add their own tables in their own schema file; they do not edit this one.
 */

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow().$onUpdate(() => new Date()),
};

/** A customer history repository (git). The worker is the only writer. */
export const historyRepos = pgTable("history_repos", {
  id: uuid("id").primaryKey().defaultRandom(),
  name: text("name").notNull().unique(),
  /** git remote URL, or null for a local-only repository */
  remoteUrl: text("remote_url"),
  /** path to a deploy key file readable by the worker (never the key itself) */
  deployKeyFile: text("deploy_key_file"),
  defaultBranch: text("default_branch").notNull().default("main"),
  pushEnabled: boolean("push_enabled").notNull().default(false),
  ...timestamps,
});

/** A registered Agent Space. No credentials are stored, only role ARNs or a profile name. */
export const agentSpaces = pgTable(
  "agent_spaces",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    alias: text("alias").notNull().unique(),
    displayName: text("display_name"),
    region: text("region").notNull(),
    accountId: text("account_id").notNull(),
    agentSpaceId: text("agent_space_id").notNull(),
    /** Role assumed for browsing, syncing and exports. Null in local mode: the base credential chain is used. */
    readRoleArn: text("read_role_arn"),
    /** Role assumed only inside apply and rollback jobs. Null in local mode. */
    writeRoleArn: text("write_role_arn"),
    /** Per-space external ID, generated by the app, used for cross-account roles. */
    externalId: text("external_id"),
    /** Optional named AWS profile for local mode (a name, never credentials). */
    awsProfile: text("aws_profile"),
    historyRepoId: uuid("history_repo_id").references(() => historyRepos.id),
    /** Per-space settings, validated by spaceSettingsSchema (src/server/spaces/settings-schema.ts). */
    settings: jsonb("settings").notNull().default(sql`'{}'::jsonb`),
    connectionStatus: text("connection_status").notNull().default("unknown"),
    connectionCheckedAt: timestamp("connection_checked_at", { withTimezone: true }),
    connectionDetail: jsonb("connection_detail"),
    ...timestamps,
  },
  (t) => [uniqueIndex("agent_spaces_space_uq").on(t.region, t.agentSpaceId)],
);

/** Users or IdP groups bound to a role, globally (spaceId null) or for one space. */
export const roleBindings = pgTable(
  "role_bindings",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    spaceId: uuid("space_id").references(() => agentSpaces.id, { onDelete: "cascade" }),
    subjectType: text("subject_type", { enum: ["user", "group"] }).notNull(),
    /** user email, or IdP group name */
    subject: text("subject").notNull(),
    role: text("role").notNull(),
    createdBy: text("created_by").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("role_bindings_uq").on(t.spaceId, t.subjectType, t.subject)],
);

/** Append-only audit log. Never update or delete rows (a trigger enforces this). */
export const auditEvents = pgTable(
  "audit_events",
  {
    id: bigserial("id", { mode: "number" }).primaryKey(),
    at: timestamp("at", { withTimezone: true }).notNull().defaultNow(),
    actorEmail: text("actor_email").notNull(),
    actorName: text("actor_name"),
    action: text("action").notNull(),
    spaceId: uuid("space_id"),
    targetType: text("target_type"),
    targetId: text("target_id"),
    result: text("result", { enum: ["ok", "error", "denied"] }).notNull().default("ok"),
    details: jsonb("details"),
  },
  (t) => [index("audit_events_at_idx").on(t.at), index("audit_events_space_idx").on(t.spaceId, t.at)],
);

/** App-level view of background jobs, for progress in the UI. pg-boss holds the queue itself. */
export const jobRuns = pgTable(
  "job_runs",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    queue: text("queue").notNull(),
    bossJobId: text("boss_job_id"),
    status: text("status", { enum: ["queued", "running", "succeeded", "failed", "cancelled"] })
      .notNull()
      .default("queued"),
    progress: real("progress").notNull().default(0),
    message: text("message"),
    actorEmail: text("actor_email").notNull(),
    spaceId: uuid("space_id"),
    input: jsonb("input"),
    result: jsonb("result"),
    error: text("error"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finishedAt: timestamp("finished_at", { withTimezone: true }),
  },
  (t) => [index("job_runs_space_idx").on(t.spaceId, t.createdAt), index("job_runs_queue_idx").on(t.queue, t.status)],
);

/** Loaded policy versions. */
export const policies = pgTable("policies", {
  id: uuid("id").primaryKey().defaultRandom(),
  source: text("source", { enum: ["app", "history"] }).notNull(),
  historyRepoId: uuid("history_repo_id").references(() => historyRepos.id),
  commit: text("commit"),
  digest: text("digest").notNull(),
  content: jsonb("content").notNull(),
  loadedAt: timestamp("loaded_at", { withTimezone: true }).notNull().defaultNow(),
});
